// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether decoding is
// currently inside a visible constrained span, and the active constrained SMILES
// prefix (`currentConstrainedOut`). Outside a span it generates freely, but it
// also watches for a naturally emitted opening delimiter `"<<"`; if no span is
// active yet, it may explicitly open one so the molecular string is produced
// under parser control.
// 
// Inside the span, the parser is the hard authority. The strategy chooses among
// three constrained actions based on simple observations of the current SMILES
// prefix: when the parser state is narrow or looks dead-end-prone it uses a
// strict single-token constrained step; otherwise it uses an adaptive
// group-aware constrained step that softly prefers caller-provided token groups;
// and when the constrained prefix has grown enough to risk repetition it adds a
// safe repetition penalty. As soon as the parser reports a complete SMILES
// prefix, the strategy closes the constrained span.
// 
// These tracked states support valid SMILES generation because every committed
// inside-span token is produced by a helper whose contract preserves parser
// validity, and span open/close transitions keep `currentConstrainedOut` aligned
// with the visible constrained segment.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span branch, either we stay outside
//   constrained mode, making the implication vacuous, or we enter a span via
//   OpenConstrainedSpan / observing `"<<“`, both of which set
//   currentConstrainedOut := [], and the precondition gives parser.IsValidPrefix([]).
//   In the complete-prefix branch, CloseConstrainedSpan exits constrained mode,
//   so the implication is again vacuous.
// 
// parser_validity: In the active constrained branch, ConstrainedStep,
//   AdaptiveConstrainedStep, and SafeRepetitionPenaltyStep each return either
//   EOS or a token that preserves parser validity. On EOS we break without
//   changing the constrained prefix; otherwise AppendConstrainedToken commits
//   that valid token, so parser.IsValidPrefix(currentConstrainedOut) is
//   preserved.
// 
// progress: The outside-span free-token branch uses UnconstrainedStep, so
//   steps increases by 1 and visible output grows by at most one token. The
//   explicit OpenConstrainedSpan branch also consumes exactly one token-step and
//   appends exactly the visible delimiter, so |generated| <= |generatedPrefix| +
//   steps is preserved.
// 
// progress: The complete-prefix close branch consumes one token-step via
//   CloseConstrainedSpan and appends at most the closing delimiter. Each active
//   constrained decoding branch consumes one token-step via its chosen helper;
//   AppendConstrainedToken adds at most that one visible token, while the EOS
//   sub-branch appends nothing. Therefore every branch preserves
//   |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var spanStarted: bool := insideConstrained || helpers.CountTokenOccurrences(generatedPrefix, "<<") > 0;
var narrowThreshold: nat := 12;
var repeatThreshold: nat := 8;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if !spanStarted {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      spanStarted := true;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          insideConstrainedOut := true;
          currentConstrainedOut := [];
          spanStarted := true;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var next := eosToken;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    var deadEndRisk := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);

    if deadEndRisk || validCount <= narrowThreshold {
      next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    } else if |currentConstrainedOut| >= repeatThreshold {
      next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
    } else {
      next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

